/* @flow */
import createSagaMiddleware from '../node_modules/redux-saga';
import * as reduxSaga from '../node_modules/redux-saga';
import { takeEvery, takeLatest, throttle } from 'redux-saga/effects';

function createSagaMiddlewareCompat(...args) {
  const sagaMiddleware = createSagaMiddleware(...args);
  const run = sagaMiddleware.run.bind(sagaMiddleware);

  sagaMiddleware.run = (...runArgs) => {
    const task = run(...runArgs);

    if (
      task &&
      task.done === undefined &&
      typeof task.toPromise === 'function'
    ) {
      task.done = task.toPromise();
    }

    return task;
  };

  return sagaMiddleware;
}

export const CANCEL = reduxSaga.CANCEL;
export const END = reduxSaga.END;
export const SAGA_LOCATION = reduxSaga.SAGA_LOCATION;
export const buffers = reduxSaga.buffers;
export const channel = reduxSaga.channel;
export const detach = reduxSaga.detach;
export const eventChannel = reduxSaga.eventChannel;
export const isEnd = reduxSaga.isEnd;
export const multicastChannel = reduxSaga.multicastChannel;
export const runSaga = reduxSaga.runSaga;
export const stdChannel = reduxSaga.stdChannel;
export { takeEvery, takeLatest, throttle };

export default createSagaMiddlewareCompat;
